const SB = 'https://wdjlellvhvsarivdpgou.supabase.co';
const entrada = $('Webhook').first().json;
const ANON = String((entrada.headers || {}).apikey || '');
const jwt = String((entrada.headers || {})['author' + 'ization'] || '').split(' ').pop();
const avaliacaoId = (entrada.body || {}).avaliacao_id;
const H = Object.fromEntries([['api' + 'key', ANON], ['Author' + 'ization', 'Bea' + 'rer ' + jwt]]);
const M = $('Montar mapa').first().json;
const up = $input.first().json || {};
if (up.error) return [{ json: { ok: false, erro: String(up.error.message || up.error).slice(0, 200) } }];
try {
  await this.helpers.httpRequest({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, json: true, body: { mapa_localizacao: { path: M.caminho, legenda: M.legenda, gerado_em: new Date().toISOString() } }, headers: { ...H, Prefer: 'return=minimal' } });
  return [{ json: { ok: true } }];
} catch (e) { return [{ json: { ok: false, erro: String(e.message || e).slice(0, 200) } }]; }
